"""Secondary reanalysis of the authors' recorded OpenHands runs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def add_map(w):
    results=json.loads((ROOT/'results.json').read_text(encoding='utf8'))
    w.page('Внешняя проверка   /   Memory as a Map','Что меняется, если открыть журнал действий целиком',
           'В другом открытом исследовании авторы запускали OpenHands с Qwen3.6-35B-A3B и разными представлениями одной заранее выбранной прошлой траектории. Мы сопоставили 380 зарегистрированных исходов с датами соответствующих GitHub PR.')
    names={'all':'Все задачи','past':'Источник уже был влит','later':'Другой PR, влит позднее¹','same_fix':'Тот же целевой PR'}
    data=[]
    for key,title in names.items():
        v=results[key]
        data.append([title,str(v['n']),*[str(v['arms'][m]['solved']) for m in ['no_memory','raw','adp','memory']]])
    w.tbl(['Источник','Задач','Без памяти','Вся траектория','Действия','Выжимка'],data,[4.5,1.8,2.5,3.3,2.5,2.5],True)
    w.p('Числа в четырёх правых столбцах — задачи, которые решили агенты авторов. В релизе 96 пар. Авторы исключили один недействительный образ Django до расчёта итогов. Остались 95 пар и 83 различных целевых PR. Во всех четырёх вариантах наши суммы решённых задач и непустых патчей совпали с опубликованными. Стратификацию по датам зафиксировали до открытия индивидуальных результатов.','Caption')
    w.p('¹ Другая реализация стала доступна при отсечении или позже. Если совпадает целевой PR, отнесение в последнюю строку имеет приоритет. Совпадение номера PR указывает на общий источник разработки. Содержимое, увиденное моделью, зависит от представления истории.')
    w.p('Все 17 допустимых по времени пар относятся к разным целевым PR. При полной траектории четыре задачи сменили исход с неуспеха на успех, одна — в обратном направлении. При передаче только действий таких задач две и ноль, при выжимке — одна и одна. Внешние исследователи запускали свой решатель и задавали готовую пару. В нашей проверке мы переоценили уже опубликованные исходы и их происхождение.')
    w.source('Memory as a Map, авторский архив, зафиксированная ревизия','https://huggingface.co/datasets/shshwtsuthar/memory-representation-contextbench-artifacts/tree/9627d0644082d387f209658610839233f761d20b')
    w.page('Связь с опубликованными результатами','Какой механизм ещё стоит проверять',
           'Полная траектория сохраняет неудачные проверки, выполненные команды и порядок наблюдений. На 17 доступных историях есть примеры выигрыша и проигрыша. Отделить пользу этих действий от длины подсказки и знания конкретного файла можно управляемой заменой одного поля в одной и той же сессии.')
    w.p('Дизайн внешнего исследования позволяет сравнивать форматы в пределах задачи. Временна́я группа задаётся историей репозитория. Репозиторий, сложность и содержание истории могут отличаться между группами. Повторно вычислить влияние отдельных команд по всему набору нельзя: авторы прямо указывают на пропуски в событийных записях OpenHands. Наша таблица использует полные итоговые оценки и датированные источники.')
    w.p('В MemDev-Bench задачи решаются с ранее доступными историями. Авторы связывают часть пользы полных траекторий с процедурами работы, включая поиск места для исправления. Этот корпус подходит для переноса метода с новым набором репозиториев и независимой разметкой. В PMCoder текущий этап плана уже управляет извлечением событий из памяти, а история действий помогает обнаружить застревание. Значит, один факт наличия журнала действий или триггера недостаточен для заявки на новизну.')
    w.p('MemUse рассматривает отдельный момент доставки записи и отслеживает следующие действия агента. В 8 000 эпизодов SWE-bench Verified близкие итоговые доли решения скрывали различия в пригодности записей. Для нашей постановки можно дополнить тесты исполняемых патчей измерениями повторно прочитанных файлов, повторных неудачных команд и времени до первой подтверждённой правки. Доказательство причинного эффекта требует контролируемого предъявления истории.')
    w.p('Авторы SWE-ContextBench в §2.3.3 намеренно включают несколько задач, закрытых общим PR. В приложении A MemDev-Bench прямо обсуждаются отсутствие обязательного временного порядка и общие PR в SWE-ContextBench. Наш потенциальный вклад — воспроизводимые количества, чувствительность метрик к выбору даты и разбор реальных результатов читателей и решателей.','Caption')
    w.source('MemDev-Bench, раздел о бенчмарках и перенос процесса','https://arxiv.org/html/2610.27524v1')
    w.source('PMCoder, управление извлечением по этапу задачи','https://arxiv.org/abs/2608.06811')
    w.source('MemUse, оценка памяти в момент её использования','https://arxiv.org/abs/2611.01718')

